macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Initialize EntryPointContract
  *
  * guarantee INITIAL_TEST_CYCLE
  * @param committedTestCycle post-state state variable
  * @param api_cycle_assessment outgoing data port
  */
pub fn initialize_INITIAL_TEST_CYCLE(
  committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  api_cycle_assessment: Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Idle) &
    (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Idle)
}

