/** Compute Entrypoint Contract
  *
  * guarantee PRE_UPDATE_CYCLE_ASSESSMENT
  * @param In_committedTestCycle pre-state state variable
  * @param api_self_test_observation incoming data port
  * @param api_cycle_assessment outgoing data port
  */
pub fn compute_spec_PRE_UPDATE_CYCLE_ASSESSMENT_guarantee(
  In_committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  api_self_test_observation: Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation,
  api_cycle_assessment: Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) &
    (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::NoEvent) &
    (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::AwaitingStart) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::FreshPass) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::StartPassed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::FreshFail) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Failed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Invalid) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::NoEvent) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::AwaitingRecovery) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::FreshPass) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::RecoveryPassed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::FreshFail) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Failed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Invalid) |
    ((In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::StartPassed) |
      (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::RecoveryPassed)) &
      (api_self_test_observation == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Invalid) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Idle) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Idle) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::StartPassed) &
      (api_self_test_observation != Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::StartPassed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::RecoveryPassed) &
      (api_self_test_observation != Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::RecoveryPassed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Failed) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Failed) |
    (In_committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Invalid) &
      (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Invalid)
}

/** Compute Entrypoint Contract
  *
  * guarantee INDEPENDENT_TEST_CYCLE_STORAGE
  * @param committedTestCycle post-state state variable
  * @param api_test_cycle_directive incoming data port
  * @param api_cycle_assessment outgoing data port
  */
pub fn compute_spec_INDEPENDENT_TEST_CYCLE_STORAGE_guarantee(
  committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  api_test_cycle_directive: Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective,
  api_cycle_assessment: Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  (api_test_cycle_directive == Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective::Clear) &
    (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Idle) |
    (api_test_cycle_directive == Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective::BeginStart) &
      (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) |
    (api_test_cycle_directive == Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective::BeginRecovery) &
      (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) |
    (api_test_cycle_directive == Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective::None) &
      ((api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Idle) &
        (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Idle) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::AwaitingStart) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingStart) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::AwaitingRecovery) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::AwaitingRecovery) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::StartPassed) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::StartPassed) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::RecoveryPassed) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::RecoveryPassed) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Failed) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Failed) |
        (api_cycle_assessment == Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment::Invalid) &
          (committedTestCycle == Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle::Invalid))
}

/** CEP-T-Guar: Top-level guarantee contracts for behavior's compute entrypoint
  *
  * @param In_committedTestCycle pre-state state variable
  * @param committedTestCycle post-state state variable
  * @param api_self_test_observation incoming data port
  * @param api_test_cycle_directive incoming data port
  * @param api_cycle_assessment outgoing data port
  */
pub fn compute_CEP_T_Guar(
  In_committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  api_self_test_observation: Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation,
  api_test_cycle_directive: Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective,
  api_cycle_assessment: Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  let r0: bool = compute_spec_PRE_UPDATE_CYCLE_ASSESSMENT_guarantee(In_committedTestCycle, api_self_test_observation, api_cycle_assessment);
  let r1: bool = compute_spec_INDEPENDENT_TEST_CYCLE_STORAGE_guarantee(committedTestCycle, api_test_cycle_directive, api_cycle_assessment);

  return r0 && r1;
}

/** CEP-Post: Compute Entrypoint Post-Condition for behavior
  *
  * @param In_committedTestCycle pre-state state variable
  * @param committedTestCycle post-state state variable
  * @param api_self_test_observation incoming data port
  * @param api_test_cycle_directive incoming data port
  * @param api_cycle_assessment outgoing data port
  */
pub fn compute_CEP_Post(
  In_committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  committedTestCycle: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle,
  api_self_test_observation: Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation,
  api_test_cycle_directive: Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective,
  api_cycle_assessment: Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  // CEP-Guar: guarantee clauses of behavior's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_committedTestCycle, committedTestCycle, api_self_test_observation, api_test_cycle_directive, api_cycle_assessment);

  return r0;
}
